-- Read current genuine recovery books before an independent hold-clearance
-- review. History stays immutable;an expense correction is never a release.
CREATE FUNCTION public.provider_dispute_reviewed_recovery_total(p_collection uuid,p_dispute text,p_on date) RETURNS numeric LANGUAGE plpgsql STABLE SET search_path=pg_catalog SET DateStyle='ISO,YMD' AS $$
DECLARE l record;r record;total numeric:=0;edition integer:=0;last_day date;actual jsonb;expected jsonb;BEGIN
 IF p_on IS NULL OR p_on NOT BETWEEN DATE '0001-01-01' AND DATE '9999-12-31' THEN RETURN NULL;END IF;
 SELECT loss.*,p.action loss_action,p.status loss_status,p.target_id loss_target,p.reviewer_id loss_reviewer,p.payload loss_payload,j.id loss_journal,j.approval_id loss_journal_approval,j.posted_by loss_posted_by,j.posted_on loss_on,j.purpose loss_purpose,j.line_count loss_lines,j.reference loss_reference,j.reverses_id loss_reverses,j.period_id loss_period,j.period_version loss_period_version INTO l FROM public.provider_dispute_losses loss LEFT JOIN public.approval_requests p ON p.academy_id=loss.academy_id AND p.id=loss.approval_id LEFT JOIN public.finance_journals j ON j.academy_id=loss.academy_id AND j.id=loss.id WHERE loss.collection_id=p_collection AND loss.dispute_id=p_dispute;
 IF l.id IS NULL OR l.posted_on>p_on OR l.loss_action IS DISTINCT FROM 'finance.provider-dispute.loss' OR l.loss_status IS DISTINCT FROM 'applied' OR l.loss_target IS DISTINCT FROM l.id OR l.loss_reviewer IS DISTINCT FROM l.created_by OR l.loss_journal IS NULL OR l.loss_journal_approval IS DISTINCT FROM l.approval_id OR l.loss_posted_by IS DISTINCT FROM l.created_by OR l.loss_on IS DISTINCT FROM l.posted_on OR l.loss_purpose IS DISTINCT FROM 'activity' OR l.loss_lines IS DISTINCT FROM 2 OR l.loss_reference IS DISTINCT FROM 'provider-dispute-loss:'||l.id::text OR l.loss_reverses IS NOT NULL OR l.loss_period IS DISTINCT FROM(l.loss_payload#>>'{period,id}')::uuid OR l.loss_period_version IS DISTINCT FROM(l.loss_payload#>>'{period,version}')::integer OR l.source->>'disposition' IS DISTINCT FROM 'academy_expense' OR l.source->>'taxTreatment' IS DISTINCT FROM 'not_claimed' OR(l.source->>'amountMinor')::numeric IS DISTINCT FROM l.amount_minor OR EXISTS(SELECT 1 FROM public.finance_journals v WHERE v.academy_id=l.academy_id AND v.reverses_id=l.id) THEN RETURN NULL;END IF;
 SELECT jsonb_agg(jsonb_build_object('accountId',account_id,'accountVersion',account_version,'side',side,'amountMinor',trunc(amount_minor)::text) ORDER BY line_number) INTO actual FROM public.finance_journal_lines WHERE academy_id=l.academy_id AND journal_id=l.id;
 expected=jsonb_build_array(jsonb_build_object('accountId',l.expense_account,'accountVersion',l.source->'expenseVersion','side','debit','amountMinor',trunc(l.amount_minor)::text),jsonb_build_object('accountId',l.disputed_account,'accountVersion',l.source->'disputedVersion','side','credit','amountMinor',trunc(l.amount_minor)::text));IF actual IS DISTINCT FROM expected OR l.source->'lines' IS DISTINCT FROM expected THEN RETURN NULL;END IF;last_day=l.posted_on;
 FOR r IN SELECT recovery.*,p.action,p.status,p.target_id,p.target_version,p.privacy_capability,p.reviewer_id,p.review_context,p.payload,j.id journal_id,j.posted_on journal_on,j.posted_by,j.approval_id journal_approval,j.period_id,j.period_version,j.purpose,j.line_count,j.reference,j.reverses_id
 FROM public.provider_dispute_loss_recoveries recovery LEFT JOIN public.approval_requests p ON p.academy_id=recovery.academy_id AND p.id=recovery.approval_id LEFT JOIN public.finance_journals j ON j.academy_id=recovery.academy_id AND j.id=recovery.id WHERE recovery.academy_id=l.academy_id AND recovery.loss_id=l.id ORDER BY recovery.recovery_no LOOP
  IF r.collection_id IS DISTINCT FROM l.collection_id OR r.dispute_id IS DISTINCT FROM l.dispute_id OR r.recovery_no<>edition+1 OR r.posted_on<last_day OR r.posted_on>p_on OR r.amount_minor<=0 OR total+r.amount_minor>l.amount_minor OR r.source->>'lossId' IS DISTINCT FROM l.id::text OR r.source->>'collectionId' IS DISTINCT FROM l.collection_id::text OR r.source->>'disputeId' IS DISTINCT FROM l.dispute_id OR r.source->>'postedOn' IS DISTINCT FROM r.posted_on::text OR(r.source->>'expectedVersion')::integer IS DISTINCT FROM edition OR(r.source->>'previouslyRecoveredMinor')::numeric IS DISTINCT FROM total OR(r.source->>'originalLossMinor')::numeric IS DISTINCT FROM l.amount_minor OR(r.source->>'remainingLossMinor')::numeric IS DISTINCT FROM l.amount_minor-total-r.amount_minor OR(r.source->>'amountMinor')::numeric IS DISTINCT FROM r.amount_minor
  OR r.source->'currencyId' IS DISTINCT FROM l.source->'currencyId' OR r.source->'currencyCode' IS DISTINCT FROM l.source->'currencyCode' OR r.source->'unitScale' IS DISTINCT FROM l.source->'unitScale' OR r.source->>'disputedAccountId' IS DISTINCT FROM l.disputed_account::text OR r.source->>'expenseAccountId' IS DISTINCT FROM l.expense_account::text
  OR r.action IS DISTINCT FROM 'finance.provider-dispute.recover-loss' OR r.status IS DISTINCT FROM 'applied' OR r.target_id IS DISTINCT FROM r.id OR r.target_version IS DISTINCT FROM 0 OR r.privacy_capability IS DISTINCT FROM 'dispute-losses.view' OR r.reviewer_id IS DISTINCT FROM r.created_by OR r.review_context->'source' IS DISTINCT FROM r.source OR r.journal_id IS NULL OR r.journal_approval IS DISTINCT FROM r.approval_id OR r.posted_by IS DISTINCT FROM r.created_by OR r.journal_on IS DISTINCT FROM r.posted_on OR r.purpose IS DISTINCT FROM 'activity' OR r.line_count IS DISTINCT FROM 2 OR r.reference IS DISTINCT FROM 'provider-dispute-loss-recovery:'||r.id::text OR r.reverses_id IS NOT NULL OR r.period_id IS DISTINCT FROM(r.payload#>>'{period,id}')::uuid OR r.period_version IS DISTINCT FROM(r.payload#>>'{period,version}')::integer OR EXISTS(SELECT 1 FROM public.finance_journals v WHERE v.academy_id=r.academy_id AND v.reverses_id=r.id) THEN RETURN NULL;END IF;
  SELECT jsonb_agg(jsonb_build_object('accountId',account_id,'accountVersion',account_version,'side',side,'amountMinor',trunc(amount_minor)::text) ORDER BY line_number) INTO actual FROM public.finance_journal_lines WHERE academy_id=r.academy_id AND journal_id=r.id;
  expected=jsonb_build_array(jsonb_build_object('accountId',l.disputed_account,'accountVersion',r.source->'disputedVersion','side','debit','amountMinor',trunc(r.amount_minor)::text),jsonb_build_object('accountId',l.expense_account,'accountVersion',r.source->'expenseVersion','side','credit','amountMinor',trunc(r.amount_minor)::text));IF actual IS DISTINCT FROM expected OR r.source->'lines' IS DISTINCT FROM expected THEN RETURN NULL;END IF;
  total=total+r.amount_minor;edition=r.recovery_no;last_day=r.posted_on;
 END LOOP;RETURN total;
 EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_parameter_value THEN RETURN NULL;
END $$;
DO $$ DECLARE d text;needle text;BEGIN
 d=pg_get_functiondef('public.provider_dispute_resolution_eligible(jsonb,boolean,boolean)'::regprocedure);d=replace(d,'factor numeric;','factor numeric;recovered numeric;');
 needle=$q$OR m->'amountMatched' IS DISTINCT FROM 'true'::jsonb$q$;IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'RECOVERED_CLEARANCE_MOVEMENT_BASE_CHANGED';END IF;d=replace(d,needle,$r$OR(m->'amountMatched' IS DISTINCT FROM 'true'::jsonb AND NOT((m->>'grossMinor')::numeric>0 AND(m->>'grossMinor')::numeric<(c.value->>'amountMinor')::numeric))$r$);
 needle=$q$IF debits<>(k->>'amountMinor')::numeric THEN RETURN false;END IF;$q$;IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'RECOVERED_CLEARANCE_SUM_BASE_CHANGED';END IF;d=replace(d,needle,needle||$r$recovered=public.provider_dispute_reviewed_recovery_total((s->>'collectionId')::uuid,k->>'disputeId',(s->>'on')::date);$r$);
 needle=$q$OR EXISTS(SELECT 1 FROM public.provider_dispute_losses loss WHERE loss.collection_id=(s->>'collectionId')::uuid AND loss.dispute_id=k->>'disputeId')$q$;IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'RECOVERED_CLEARANCE_RETURNED_BASE_CHANGED';END IF;d=replace(d,needle,$r$OR EXISTS(SELECT 1 FROM public.provider_dispute_losses loss WHERE loss.collection_id=(s->>'collectionId')::uuid AND loss.dispute_id=k->>'disputeId' AND(recovered IS NULL OR recovered<>loss.amount_minor))$r$);
 needle='returns>=debits';IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'RECOVERED_CLEARANCE_LOST_SUM_BASE_CHANGED';END IF;d=replace(d,needle,'returns>debits OR recovered IS NULL');
 needle='l.amount_minor<>(debits-returns)*factor';IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'RECOVERED_CLEARANCE_LOSS_BASE_CHANGED';END IF;EXECUTE replace(d,needle,'l.amount_minor-recovered<>(debits-returns)*factor');
END $$;
REVOKE ALL ON FUNCTION public.provider_dispute_reviewed_recovery_total(uuid,text,date) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.provider_dispute_reviewed_recovery_total(uuid,text,date) TO kavosh_runtime;
CREATE OR REPLACE FUNCTION public.schema_revision() RETURNS integer LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT 339 $$;
